function sortableHeading(key, label) {
  const active = sortKey === key;
  const direction = sortAsc ? 'ascending' : 'descending';
  const arrow = active ? ` <span aria-hidden="true">${sortAsc ? '↑' : '↓'}</span>` : '';
  return `<th scope="col"${active ? ` aria-sort="${direction}"` : ''}><button data-sort="${key}">${label}${arrow}</button></th>`;
}
function compareRows(a, b) {
  const left = sortKey === 'score' ? value(a) : num(a, sortKey);
  const right = sortKey === 'score' ? value(b) : num(b, sortKey);
  if (left === null || right === null) return Number(left === null) - Number(right === null);
  return sortAsc ? left - right : right - left;
}
