document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;hazardView=false;if($('#hazard-view'))$('#hazard-view').checked=false;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));draw();render()});document.querySelectorAll('[name=indicator]').forEach(i=>i.onchange=()=>{indicator=i.value;hazardView=false;if($('#hazard-view'))$('#hazard-view').checked=false;draw();render()});$('#opacity').oninput=e=>{opacity=e.target.value/100;draw()};$('#basemap').onchange=e=>{if(base)map.removeLayer(base);base=bases[e.target.value];if(base)base.addTo(map)};$('#reset-map').onclick=()=>map.setView([35.99,-84],8);$('#search').oninput=e=>{$('#search-results').innerHTML=e.target.value?data().filter(r=>(r.LOCATION+' '+r.FIPS).toLowerCase().includes(e.target.value.toLowerCase())).slice(0,6).map(r=>`<button data-find="${r.FIPS}">${name(r)} · ${r.COUNTY}</button>`).join('')||'<p role="status">No matching community. Try a county name or FIPS.</p>':'';document.querySelectorAll('[data-find]').forEach(b=>b.onclick=()=>{select(data().find(r=>r.FIPS===b.dataset.find),true);$('#search-results').innerHTML=''})};window.addEventListener('hashchange',render);
function section(title,body,tag='RESEARCH WORKSPACE'){return`<section class="section"><div class="eyebrow">${tag}</div><h2>${title}</h2>${body}</section>`}
function countyOptions(v,all=false){return`${all?'<option value="all">All East Tennessee counties</option>':''}${[...EAST].sort().map(n=>`<option ${v===n?'selected':''}>${n}</option>`).join('')}`}
function serviceOptions(){return[['hospital','Hospitals / medical centers'],['fire','Fire / EMS'],['ambulance','Ambulance services'],['police','Police stations'],['grocery','SNAP grocery retailers'],['library','Public libraries']].map(([v,n])=>`<option value="${v}" ${v===service?'selected':''}>${n}</option>`).join('')}
function distance(a,b){const rad=Math.PI/180,p=(b.lat-a.lat)*rad,q=(b.lng-a.lng)*rad;const x=Math.sin(p/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(q/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
