function priorityPage(){return section('Potential priority areas',`<p>Areas where additional resilience resources or further study may be valuable. Click a column to sort, or a community to zoom to its profile.</p><div class="notice">Combined priority = mean of the selected vulnerability measure, normalized service proximity, and FEMA ${hazardNames()[hazard]} expected annual loss score. County hazard context is assigned to tracts; it does not resolve exposure within a tract.</div><button id="export">↓ Download current analysis</button>${table(2000)}`)}
function accessPage(){let rows=data().filter(r=>r.distance!==null),population=rows.reduce((s,r)=>s+Number(r.E_TOTPOP),0),mean=rows.reduce((s,r)=>s+r.distance*Number(r.E_TOTPOP),0)/(population||1);return section('Service accessibility',`<p>Which communities are geographically farthest from mapped critical services?</p><div class="tool-links"><a href="#network">Calculate a driving route ↗</a><a href="#placement">Explore resource placement ↗</a></div><label class="field">Service type<select id="service-select">${serviceOptions()}</select></label><div class="notice">Method: great-circle distance from each area's boundary-box center to the nearest mapped facility. Distances here are in kilometers. Regional driving times are not precomputed; use Driving routes for a selected community. Threshold populations are area-level screening estimates, not measured household access.</div><div class="grid3">${[[mean.toFixed(1)+' km','Population-weighted mean proximity'],[fmt(rows.filter(r=>r.distance>20).reduce((s,r)=>s+Number(r.E_TOTPOP),0)),'Residents in areas with center >20 km away'],[fmt(rows.filter(r=>r.distance>30).reduce((s,r)=>s+Number(r.E_TOTPOP),0)),'Residents in areas with center >30 km away']].map(([n,t])=>`<div class="card"><div class="big">${n}</div><p>${t}</p></div>`).join('')}</div><h3>Most geographically isolated areas</h3>${isolationTable(rows)}<p class="small">Emergency-department status, designated emergency shelters, pharmacies, and community centers require additional validated inventories. Grocery coverage includes USDA SNAP-authorized grocery stores, supermarkets and super stores; libraries include IMLS permanent central and branch outlets. No substitute locations have been invented.</p>`)}
function isolationTable(rows){return`<div class="table-wrap"><table><thead><tr><th>Community</th><th>Nearest mapped service</th><th>Distance</th><th>Population</th></tr></thead><tbody>${[...rows].sort((a,b)=>b.distance-a.distance).slice(0,10).map(r=>`<tr data-id="${r.FIPS}" tabindex="0"><td>${name(r)} · ${r.COUNTY}</td><td>${escapeHTML(r.nearest||'Unavailable')}</td><td>${r.distance?.toFixed(1)} km</td><td>${fmt(r.E_TOTPOP)}</td></tr>`).join('')}</tbody></table></div>`}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function scenarioPage(){return section('Infrastructure disruption scenario lab',`<p>Test how many residents live in tracts whose distance to a mapped service would cross 30 km under an assumed detour. The same extra distance applies to every tract in the selected county.</p><div class="tool-links"><a href="#outage">Test a hypothetical facility outage</a><a href="#network">Examine a baseline driving route ↗</a></div><span class="badge amber">Illustrative sensitivity analysis · no network routing</span><div class="grid2"><div><label class="field">Affected county<select id="scenario-county">${countyOptions(scenarioCounty)}</select></label><label class="field">Service<select id="scenario-service">${serviceOptions()}</select></label><label class="field">Assumed extra distance: <b id="detour-label">${detour} km</b><input id="detour" type="range" min="0" max="60" step="5" value="${detour}"></label><button id="run-scenario">Compare before & after →</button><p class="small">Start with 0 km to reproduce the baseline. Increase the penalty to explore how sensitive the threshold count is to your assumption.</p></div><div id="scenario-result"></div></div><div class="notice">The count includes every resident of a tract whose center crosses the threshold. Modeling a named bridge closure would require a dated closure record, a road network with the crossing removed, and comparable routes before and after closure. That analysis is future work.</div>`)}
function runScenario(){const rows=tractData.filter(r=>r.COUNTY===scenarioCounty+' County'&&r.distance!==null),pop=rows.reduce((s,r)=>s+Number(r.E_TOTPOP),0),before=rows.reduce((s,r)=>s+r.distance*Number(r.E_TOTPOP),0)/(pop||1),after=before+detour,newpop=rows.filter(r=>r.distance<=30&&r.distance+detour>30).reduce((s,r)=>s+Number(r.E_TOTPOP),0);$('#scenario-result').innerHTML=`<div class="grid2"><div class="card"><div class="eyebrow">BASELINE PROXIMITY</div><p class="big">${before.toFixed(1)} km</p></div><div class="card"><div class="eyebrow">ASSUMED DISRUPTION</div><p class="big">${after.toFixed(1)} km</p></div></div><div class="card" style="margin-top:18px"><div class="big">${fmt(newpop)}</div><p>Residents in tracts newly above the 30 km proxy threshold</p><span class="small">${rows.length} tracts · ${fmt(pop)} residents · uniform +${detour} km assumption</span></div>`;const r=countyData.find(r=>r.COUNTY===scenarioCounty+' County');if(r?.layer)map.fitBounds(r.layer.getBounds(),{padding:[25,25]});syncAnalysisURL();}
function profilePage(){const r=selected||countyData.find(r=>r.COUNTY==='Cocke County');const county=countyData.find(c=>c.COUNTY===r.COUNTY);const attrs=[['E_TOTPOP','Population',''],['EP_POV150','Below 150% of poverty threshold','%'],['EP_AGE65','Age 65+','%'],['EP_AGE17','Children under 18','%'],['EP_DISABL','Disability','%'],['EP_NOVEH','Households without vehicles','%'],['EP_NOINT','Households without internet','%'],['EP_MOBILE','Mobile homes','%']];return section('Community profile · '+escapeHTML(r.LOCATION),`<div class="profile-actions"><button class="pin-button" data-pin="${r.FIPS}">${shortlist.includes(r.FIPS)?'★ Remove from shortlist':'☆ Add to shortlist'}</button><a href="#shortlist">Open shortlist (${shortlist.length}) ↗</a></div><div class="grid2"><div><table><tbody>${attrs.map(([k,n,u])=>`<tr><td>${n}</td><td><b>${num(r,k)===null?'Unavailable':u?num(r,k).toFixed(1)+u:fmt(r[k])}</b></td><td class="small">${num(r,'MP_'+k.slice(3))!==null?`±${num(r,'MP_'+k.slice(3)).toFixed(1)} pp MOE`:''}</td></tr>`).join('')}<tr><td>Median household income</td><td colspan="2">Not included in SVI 2022 inventory</td></tr><tr><td>Nearest ${service}</td><td colspan="2">${escapeHTML(r.nearest||'Unavailable')}</td></tr><tr><td>Geographic proximity</td><td colspan="2">${r.distance?.toFixed(1)??'—'} km · straight line</td></tr><tr><td>FEMA ${hazardNames()[hazard]} EAL</td><td>${num(r,hazard)?.toFixed(1)??'—'} / 100</td><td class="small">County context</td></tr></tbody></table></div><div><h3>Community in context</h3><p class="small">Percent of the relevant population. Regional comparison is an unweighted county mean.</p>${attrs.slice(1,6).map(([k,n])=>`<div class="barrow"><b>${n}</b><div style="margin-top:8px">Selected area <span>${num(r,k)===null?'Unavailable':num(r,k).toFixed(1)+'%'}</span></div><div class="bartrack"><span style="width:${num(r,k)??0}%"></span></div><div style="margin-top:8px">County <span>${num(county,k)===null?'Unavailable':num(county,k).toFixed(1)+'%'}</span></div><div class="bartrack"><span style="width:${num(county,k)??0}%;background:#9ab7ad"></span></div><div style="margin-top:8px">Region <span>${avg(countyData,k).toFixed(1)}%</span></div><div class="bartrack"><span style="width:${avg(countyData,k)}%;background:#c49a54"></span></div></div>`).join('')}</div></div>`)}
function toggleShortlist(fips){if(shortlist.includes(fips))shortlist=shortlist.filter(v=>v!==fips);else if(shortlist.length<6)shortlist=[...shortlist,fips];syncAnalysisURL();render()}
function shortlistPage(){const rows=shortlist.map(f=>[...countyData,...tractData].find(r=>r.FIPS===f)).filter(Boolean);return section('Research shortlist',`<div class="content-head"><div><p>Pin up to six communities while you move through the atlas. The shortlist is included in copied analysis links and the research review brief.</p></div>${rows.length?'<button id="clear-shortlist">Clear shortlist</button>':''}</div>${rows.length?`<div class="notice">County and tract values appear together for review, but rankings should only be compared within the same geographic scale.</div><div class="shortlist-grid">${rows.map(r=>`<article class="shortlist-card"><div><span class="badge">${r.FIPS.length===11?'Census tract':'County'}</span><button class="icon-button pin-button" data-pin="${r.FIPS}" aria-label="Remove ${escapeHTML(name(r))} from shortlist">×</button></div><h3>${escapeHTML(name(r))}</h3><p class="small">${escapeHTML(r.LOCATION)}</p><dl><div><dt>Population</dt><dd>${fmt(r.E_TOTPOP)}</dd></div><div><dt>SVI</dt><dd>${num(r,'RPL_THEMES')===null?'—':(num(r,'RPL_THEMES')*100).toFixed(1)}</dd></div><div><dt>${escapeHTML(service)} proximity</dt><dd>${r.distance?.toFixed(1)??'—'} km</dd></div><div><dt>${escapeHTML(hazardNames()[hazard])} EAL</dt><dd>${num(r,hazard)?.toFixed(1)??'—'}</dd></div></dl><button class="text-button" data-id="${r.FIPS}">Open profile →</button></article>`).join('')}</div>`:'<div class="empty-state shortlist-empty"><span>☆</span><h3>No communities pinned yet</h3><p>Open a community profile from the map or a results table, then choose “Add to shortlist.”</p><a href="#priority">Browse potential priority areas →</a></div>'}`)}
function comparisonPage(){const a=countyData.find(r=>r.COUNTY===compareA+' County'),b=countyData.find(r=>r.COUNTY===compareB+' County');const vars=[['E_TOTPOP','Population',''],['density','People per square mile',''],['EP_POV150','Below 150% poverty','%'],['EP_NOVEH','Households without vehicles','%'],['EP_AGE65','Age 65+','%'],['EP_DISABL','Disability','%'],['distance',service+' proximity',' km'],['RPL_THEMES','SVI percentile',''],[hazard,'FEMA hazard EAL score','']];return section('County comparison',`<p>Compare social conditions and service proximity. Density provides context; these counties have not been formally classified as urban or rural.</p><div class="grid2"><label class="field">First county<select id="compare-a">${countyOptions(compareA)}</select></label><label class="field">Second county<select id="compare-b">${countyOptions(compareB)}</select></label></div><table><thead><tr><th>Indicator</th><th>${compareA}</th><th>${compareB}</th></tr></thead><tbody>${vars.map(([k,n,u])=>`<tr><td>${n}</td><td><b>${num(a,k)===null?'—':k==='RPL_THEMES'?(num(a,k)*100).toFixed(1):num(a,k).toLocaleString(undefined,{maximumFractionDigits:1})}${u}</b></td><td><b>${num(b,k)===null?'—':k==='RPL_THEMES'?(num(b,k)*100).toFixed(1):num(b,k).toLocaleString(undefined,{maximumFractionDigits:1})}${u}</b></td></tr>`).join('')}</tbody></table><p class="small">Service proximity is measured from county centers and may conceal large within-county differences. Use census tracts in the map for a more detailed view.</p>`)}
function explorerPage(){const rows=data().filter(r=>filterCounty==='all'||r.COUNTY===filterCounty+' County');return section('Data explorer',`<p>Examine associations between demographic indicators and geographic service proximity.</p><label class="field">Geographic resolution<select id="explorer-geo"><option value="county" ${geo==='county'?'selected':''}>Counties</option><option value="tract" ${geo==='tract'?'selected':''}>Census tracts</option></select></label><div class="grid2"><label class="field">County filter<select id="explorer-county">${countyOptions(filterCounty,true)}</select></label><label class="field">Horizontal axis<select id="explorer-x">${[['EP_POV150','Below 150% poverty (%)'],['EP_NOVEH','Households without vehicles (%)'],['EP_AGE65','Age 65+ (%)'],['density','Population density']].map(([v,n])=>`<option value="${v}" ${v===explorerX?'selected':''}>${n}</option>`).join('')}</select></label></div>${scatter(rows,explorerX,'distance')}<p class="small">Each point is an area. Hover or focus to inspect it. Vertical axis: nearest ${service} distance in km. Descriptive exploration only; association does not establish causation.</p><button id="export">↓ Download filtered data</button>${isolationTable(rows)}`)}
function screenRows(){return(screenGeo==='tract'?tractData:countyData).filter(r=>(screenCounty==='all'||r.COUNTY===screenCounty+' County')&&num(r,'RPL_THEMES')!==null&&r.distance!==null&&num(r,hazard)!==null&&num(r,'RPL_THEMES')*100>=screenSVI&&r.distance>=screenDistance&&num(r,hazard)>=screenHazard).sort((a,b)=>Number(b.RPL_THEMES)-Number(a.RPL_THEMES)||b.distance-a.distance)}
function screeningPage(){const rows=screenRows(),population=rows.reduce((s,r)=>s+Number(r.E_TOTPOP||0),0);return section('Threshold screening workbench',`<p>Find communities that meet every selected threshold. This is a transparent query over loaded evidence, not a new composite score.</p><div class="screen-controls"><label class="field">Geography<select id="screen-geo"><option value="county" ${screenGeo==='county'?'selected':''}>Counties</option><option value="tract" ${screenGeo==='tract'?'selected':''}>Census tracts</option></select></label><label class="field">County scope<select id="screen-county">${countyOptions(screenCounty,true)}</select></label><label class="field">Service<select id="screen-service">${serviceOptions()}</select></label><label class="field">Minimum SVI: <b id="screen-svi-label">${screenSVI.toFixed(0)} / 100</b><input id="screen-svi" type="range" min="0" max="100" step="5" value="${screenSVI}"></label><label class="field">Minimum ${service} proximity: <b id="screen-distance-label">${screenDistance.toFixed(0)} km</b><input id="screen-distance" type="range" min="0" max="60" step="5" value="${screenDistance}"></label><label class="field">Minimum ${escapeHTML(hazardNames()[hazard])} EAL: <b id="screen-hazard-label">${screenHazard.toFixed(0)} / 100</b><input id="screen-hazard" type="range" min="0" max="100" step="5" value="${screenHazard}"></label></div><div class="tool-links"><button id="reset-screen">Reset thresholds</button><button id="export-screen" ${rows.length?'':'disabled'}>↓ Download ${rows.length} matches</button></div><div class="grid2 screen-summary"><div class="card"><div class="big">${fmt(rows.length)}</div><p>communities meet all thresholds</p></div><div class="card"><div class="big">${fmt(population)}</div><p>residents represented in matching areas</p></div></div><div class="notice">Missing SVI, proximity, or hazard inputs are excluded. Tract results inherit county-level hazard context. Population totals describe residents of matching areas and do not estimate individual exposure or service access.</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Community</th><th>Scale</th><th>SVI</th><th>${escapeHTML(service)} proximity</th><th>${escapeHTML(hazardNames()[hazard])} EAL</th><th>Population</th></tr></thead><tbody>${rows.map(r=>`<tr data-id="${r.FIPS}" tabindex="0"><td><b>${escapeHTML(name(r))}</b><br><span class="small">${escapeHTML(r.COUNTY)}</span></td><td>${r.FIPS.length===11?'Tract':'County'}</td><td>${(num(r,'RPL_THEMES')*100).toFixed(1)}</td><td>${r.distance.toFixed(1)} km</td><td>${num(r,hazard).toFixed(1)}</td><td>${fmt(r.E_TOTPOP)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><span>⌕</span><h3>No communities meet every threshold</h3><p>Lower one or more thresholds or broaden the county scope.</p></div>'}`)}
function bindScreen(){if(!$('#screen-geo'))return;$('#screen-geo').onchange=e=>{screenGeo=e.target.value;render()};$('#screen-county').onchange=e=>{screenCounty=e.target.value;render()};$('#screen-service').onchange=e=>{service=e.target.value;computeAccess();render()};for(const [id,key,label,suffix]of[['screen-svi','svi','screen-svi-label',' / 100'],['screen-distance','distance','screen-distance-label',' km'],['screen-hazard','hazard','screen-hazard-label',' / 100']]){$('#'+id).oninput=e=>$('#'+label).textContent=e.target.value+suffix;$('#'+id).onchange=e=>{const v=Number(e.target.value);if(key==='svi')screenSVI=v;else if(key==='distance')screenDistance=v;else screenHazard=v;render()}}$('#reset-screen').onclick=()=>{screenCounty='all';screenSVI=75;screenDistance=15;screenHazard=50;render()};$('#export-screen').onclick=exportData}
function scatter(rows,x,y){const a=rows.filter(r=>num(r,x)!==null&&num(r,y)!==null),xm=Math.max(1,...a.map(r=>Number(r[x]))),ym=Math.max(1,...a.map(r=>Number(r[y])));return`<svg class="chart" viewBox="0 0 900 350" role="group" aria-label="Scatterplot of ${x} and service distance">${[0,.25,.5,.75,1].map(t=>`<path d="M65 ${300-t*260} H870" stroke="#e2e8e9"/><text x="15" y="${305-t*260}">${(ym*t).toFixed(0)}</text><text x="${65+t*805}" y="325">${(xm*t).toFixed(1)}</text>`).join('')}${a.map(r=>`<circle role="button" aria-label="${escapeHTML(r.LOCATION)}: ${Number(r[x]).toFixed(1)}; service distance ${Number(r[y]).toFixed(1)} km. Open community profile." data-id="${r.FIPS}" tabindex="0" cx="${65+Number(r[x])/xm*805}" cy="${300-Number(r[y])/ym*260}" r="6" fill="${color(num(r,'RPL_THEMES'))}" stroke="white" opacity=".85"><title>${escapeHTML(r.LOCATION)} · ${Number(r[x]).toFixed(1)} / ${Number(r[y]).toFixed(1)} km</title></circle>`).join('')}</svg><p class="chart-detail small" role="status">Focus a point to read its values; activate it to open the community profile.</p>`}
function hazardNames(){return{IFLD_EALS:'inland flooding',HWAV_EALS:'heat wave',TRND_EALS:'tornado',WFIR_EALS:'wildfire',LNDS_EALS:'landslide',SWND_EALS:'strong wind'}}
function methodologyPage(){return section('A transparent, configurable methodology',`<p>Weights are research modeling decisions, not objective measures of a community's worth or importance.</p><div class="flow">${['Public data','Cleaning & validation','FIPS geospatial join','Normalize indicators','Vulnerability model','Service proximity','Hazard context','Priority screening','Interactive results'].map((s,i)=>`<span>${String(i+1).padStart(2,'0')} / ${s}</span>`).join('')}</div><div class="grid2"><div class="card"><h3>Adjust the custom vulnerability model</h3>${['Economic · below 150% poverty','Transportation · no vehicle','Demographic · disability','Community access · service distance'].map((n,i)=>`<label class="field">${n} <b id="weight-label-${i}">${weights[i]} parts</b><input type="range" min="0" max="100" value="${weights[i]}" data-weight="${i}"></label>`).join('')}<button id="apply-weights">Apply weights to map</button><p id="weight-note" class="small">Weights are divided by their sum. Current normalized weights: ${weights.map(w=>(w/(weights.reduce((a,b)=>a+b,0)||1)*100).toFixed(1)+'%').join(' / ')}.</p></div><div class="card"><h3>How the calculation works</h3><p>For each selected indicator, x′ = (x − minimum) / (maximum − minimum), using all 33 counties or all loaded East Tennessee tracts. Constant indicators become zero. Missing values remain missing.</p><p>Custom vulnerability = Σ(weight × x′) / Σweights. Demographic vulnerability uses disability prevalence in this first model. The official CDC SVI remains available separately and is not recalculated with these weights.</p><p>Combined priority = (vulnerability + normalized distance + FEMA hazard EAL percentile / 100) / 3. It is a comparative screening model, not a validated risk probability. Access contributes twice if the custom vulnerability model includes access; reduce that weight to zero to avoid this overlap.</p><p>FEMA Expected Annual Loss (EAL) scores describe modeled loss potential, not direct exposure or individual risk. Tracts inherit county hazard context. Compare alternative weights before drawing conclusions.</p></div></div><div class="tool-links"><a href="#sensitivity">Compare model assumptions ↗</a><a href="#audit">Audit data quality ↗</a><a href="#brief">Prepare a research review brief ↗</a></div><h3>Data handling and uncertainty</h3><p>Geography joins use FIPS as strings, retaining leading zeros. CDC values below zero are treated as unavailable. Census estimates retain published margins of error in the download. Empty or missing inputs never become fabricated observations.</p><p>Service proximity uses great-circle distance from the bounding-box center of the source boundary. The center may fall outside an irregular polygon and is not population weighted. Every facility in the buffered study-region inventory is considered, including nearby states.</p><div class="notice">Census estimates contain uncertainty. Facility locations do not indicate capacity or current operations. Different data vintages and geographic scales affect interpretation. These results require validation before any operational use.</div><a href="data/analysis.py" download>↓ Download reproducible Python analysis</a> · <a href="data/placement.py" download>↓ Resource-placement analysis</a>`)}
function sourcesPage(){const sources=[['CDC/ATSDR Social Vulnerability Index','CDC / ATSDR · 2022 (ACS 2018–2022)','County and 2020 census tract','https://svi.cdc.gov/dataDownloads/data-download.html','Loaded · Tennessee-relative SVI ranks. Percent poverty means below 150% of the poverty threshold, not the official below-100% poverty rate. Published margins of error retained.'],['TIGERweb county boundaries','U.S. Census Bureau · current service snapshot, 2026','County polygons','https://tigerweb.geo.census.gov/arcgis/rest/services/TIGERweb/State_County/MapServer','Loaded · current county boundaries; display precision 0.001 degrees.'],['2020 census tract boundaries','U.S. Census Bureau · 2020','Census tract polygons','https://tigerweb.geo.census.gov/arcgis/rest/services/Census2020/tigerWMS_Census2020/MapServer/6','Loaded · generalized at 0.002 degrees for display. Joined to CDC 2022 by GEOID.'],['The National Map: Structures','U.S. Geological Survey · rolling inventory, snapshot 2026','Facility points','https://carto.nationalmap.gov/arcgis/rest/services/structures/MapServer','Loaded · hospitals, fire/EMS, ambulance, police. Inventory includes a buffer around East Tennessee. Record load dates and originators are retained; neither guarantees current operation.'],['National Risk Index Counties','FEMA · December 2025 (1.20.0)','County','https://www.arcgis.com/home/item.html?id=39485e8035d446a5bff03259508ae355','Loaded · expected annual loss scores for inland flooding, heat, tornado, wildfire, landslide, strong wind. Scores are hazard-loss proxies, not floodplain boundaries or incident forecasts.'],['Eastern Grand Division','Tennessee state government · accessed 2026','County membership','https://www.tn.gov/directory/county-city-web-sites.html','Loaded · 33 counties. Study area definition is independent of TDOT regions.'],['OpenStreetMap / OpenTopoMap','Basemap providers · continuously updated','Map tiles','https://www.openstreetmap.org/copyright','Context only · no OSM facility inventory or road-network results are used.'],['SNAP grocery retailers','USDA Food and Nutrition Service · snapshot September 2026','Facility points','https://www.fns.usda.gov/snap/retailer-locator','Loaded · 1,054 SNAP-authorized grocery stores, supermarkets and super stores in the regional buffer. Not a complete food-retail inventory; no opening hours, stock, or capacity. Accessed September 10, 2026.'],['Public library outlets','Institute of Museum and Library Services · FY2024','Facility points','https://www.imls.gov/research-evaluation/surveys/public-libraries-survey-pls','Loaded · 268 central/branch outlets in the regional buffer. Bookmobiles and reported temporary closures excluded. Libraries are not designated emergency shelters. Accessed September 10, 2026.'],['Driving routes and Census origins','OSRM / OpenStreetMap; Census Bureau · 2020 origins','Tract internal point to facility','https://project-osrm.org/docs/v26.4.0/http','On demand · driving estimate to fastest of five nearest candidates. No live traffic, emergency conditions, or full regional travel-time model. Coordinates are sent to OSRM.'],['Additional critical services and infrastructure','Tennessee health, TDOT, FEMA, local agencies · planned','Facility points / road network','https://www.tn.gov/tdot.html','Not loaded · emergency-department status, pharmacies, designated shelters, roads, bridges, rail, airports and transit require validated inventories and routing.']];return section('Data sources & provenance',`<p>All analytical inputs are public agency datasets. Core snapshot retrieved September 9, 2026; grocery, library and routing-origin additions September 10, 2026. The application serves frozen analytical data for reproducibility.</p>${sources.map(([n,a,g,u,l])=>`<div class="source"><h3>${n}</h3><span class="badge">${a}</span><p><b>Resolution:</b> ${g}<br><b>Accessed:</b> ${['SNAP grocery retailers','Public library outlets','Driving routes and Census origins'].includes(n)?'September 10, 2026':'September 9, 2026'}<br><b>Use & limitations:</b> ${l}</p><a href="${u}" target="_blank" rel="noopener">Open source documentation ↗</a></div>`).join('')}<p><a href="data/svi.csv" download>County SVI source CSV ↓</a> · <a href="data/facilities.json" download>Facility inventory ↓</a> · <a href="data/hazards.json" download>FEMA hazard snapshot ↓</a></p>`)}
function regionPage(){return section('East Tennessee overview',`<p>County comparisons reveal regional variation without implying that every resident shares an area's characteristics.</p><div class="grid2"><div><h3>Population distribution</h3>${countyData.slice().sort((a,b)=>Number(b.E_TOTPOP)-Number(a.E_TOTPOP)).slice(0,10).map(r=>`<div class="barrow"><div><span>${r.COUNTY}</span><b>${fmt(r.E_TOTPOP)}</b></div><div class="bartrack"><span style="width:${Number(r.E_TOTPOP)/Math.max(...countyData.map(x=>Number(x.E_TOTPOP)))*100}%"></span></div></div>`).join('')}</div><div><h3>SVI distribution</h3>${[0,1,2,3,4].map(i=>{let n=countyData.filter(r=>num(r,'RPL_THEMES')>=i*.2&&(i===4?num(r,'RPL_THEMES')<=1:num(r,'RPL_THEMES')<(i+1)*.2)).length;return`<div class="barrow"><div><span>${i*20}–${(i+1)*20} percentile</span><b>${n} counties</b></div><div class="bartrack"><span style="width:${n/33*100}%;background:${colors[i]}"></span></div></div>`}).join('')}<h3>Density & service proximity</h3>${scatter(countyData,'density','distance')}<p class="small">No formal urban–rural classification or significance test is applied.</p></div></div>`)}
function hospitalFinding() {
  return `<article class="card">
    <h3>Monroe County ranks first under both hospital-access models</h3>
    <p>Across 33 East Tennessee counties, Monroe combines a Tennessee-relative social vulnerability score of 88.3/100 with a 27.7 km straight-line distance from its county bounding-box center to the nearest mapped hospital. That distance scores 95.5/100 after scaling the shortest and longest county distances to 0 and 100. Monroe’s inland-flood expected annual loss score is 58.8/100.</p>
    <div class="table-wrap"><table><caption>Three leading counties under the baseline weights</caption>
    <thead><tr><th scope="col">County</th><th scope="col">Baseline score / 100</th><th scope="col">Baseline rank</th><th scope="col">Access-weighted rank</th></tr></thead>
    <tbody><tr><th scope="row">Monroe</th><td>81.0</td><td>1</td><td>1</td></tr>
    <tr><th scope="row">Morgan</th><td>64.4</td><td>2</td><td>2</td></tr>
    <tr><th scope="row">Hamilton</th><td>62.1</td><td>3</td><td>5</td></tr></tbody></table></div>
    <p>The baseline assigns 34% to social vulnerability, 33% to hospital distance and 33% to inland-flood loss. Changing those weights to 20%, 50% and 30% keeps Monroe and Morgan at the top. Hamilton’s high flood-loss score (95.0/100) carries less weight, and Polk moves into third place. Seven counties appear in both top tens.</p>
    <p>This fixed county-level example uses CDC SVI 2022, mapped hospital locations and FEMA’s December 2025 loss scores. A county-center distance can hide substantial differences in access between residents.</p>
    <div class="tool-links"><a href="?g=county&amp;s=hospital&amp;h=IFLD_EALS#sensitivity">Reproduce the two models</a><a href="data/county-analysis.csv" download>Download county inputs</a></div>
  </article>`;
}
function researchPage(){const highest=[...countyData].sort((a,b)=>Number(b.RPL_THEMES)-Number(a.RPL_THEMES)).slice(0,3);return section('Mapping vulnerability and critical connections',`${hospitalFinding()}<p>A geospatial analysis of population vulnerability, critical infrastructure accessibility, and community resilience.</p><div class="grid2"><article><h3>Research question</h3><p>Which communities in East Tennessee face the greatest combined risk from social vulnerability, hazard exposure, and limited access to critical services?</p><h3>Background</h3><p>Emergency access depends on social conditions, service locations, and transportation connections. This platform examines these dimensions together, while preserving the distinction between measured inputs and modeling choices.</p><h3>Study area</h3><p>The study includes all 33 counties in Tennessee's Eastern Grand Division. County summaries provide regional context; census tracts reveal smaller-area variation.</p><h3>Data sources</h3><p>CDC/ATSDR SVI 2022, Census TIGERweb boundaries, USGS structures, and FEMA National Risk Index December 2025 form the analytical snapshot. <a href="#sources">See provenance and limitations.</a></p><h3>Methodology & vulnerability model</h3><p>Data are joined by FIPS, missing indicators are excluded from scoring, and a configurable min–max composite is offered alongside the published state-relative CDC SVI. The combined screen averages vulnerability, service distance, and a selected hazard-loss percentile.</p><h3>Accessibility analysis</h3><p>Geographic proximity is measured to the nearest mapped service. It is not a road-network travel time. Scenario penalties illustrate sensitivity to assumed disruptions.</p></article><article><h3>Results</h3><p>In the loaded CDC snapshot, ${highest.map(r=>r.COUNTY).join(', ')} have the highest county SVI ranks within this study area. ${countyData.filter(r=>num(r,'RPL_THEMES')>=.8).length} study counties have a Tennessee-relative SVI at or above 0.80.</p><h3>Geographic patterns</h3><p>Use the <a href="#region">regional overview</a> and <a href="#explorer">data explorer</a> to inspect the actual spatial and descriptive patterns. County aggregation can obscure differences within communities; findings should be checked at tract scale.</p><h3>Limitations</h3><p>ACS uncertainty, facility completeness, service capacity, mixed data vintages, center-point bias, and model weighting limit interpretation. County hazard scores cannot identify exposure within a tract. Correlation does not establish causation.</p><h3>Future research</h3><p>Integrate verified roads and bridge closures, population-weighted origins, validated travel speeds, emergency-service capacity, household income, and additional service inventories. Test sensitivity, spatial autocorrelation, and alternative resource-placement models with local partners.</p><h3>Conclusion</h3><p>This platform supports transparent exploratory screening and reproducible hypothesis generation. Its rankings identify areas for further study; they do not establish operational emergency priorities.</p></article></div><div class="notice">This project is an exploratory academic geospatial analysis and is not intended to replace official emergency-management planning.</div>`)}
function aboutPage(){return section('Project overview',`<p>Mapping Community Vulnerability and Critical-Service Accessibility in East Tennessee</p><div class="grid2">${[['The problem','Communities can experience different levels of vulnerability during emergencies depending on demographics, infrastructure, transportation, and geographic accessibility.'],['The question','Where do community vulnerability and limited access to critical services overlap in East Tennessee?'],['The approach','Integrate public demographic data, infrastructure locations, geographic proximity, and hazard-loss indicators through GIS. Preserve provenance and make assumptions inspectable.'],['The result','A reproducible exploratory atlas with tract profiles, county comparisons, configurable screening, and a scenario sensitivity lab. Findings are available for further validation.']].map(([t,p])=>`<div class="card"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><h3>Skills demonstrated</h3><div class="flow">${['GIS','Spatial analysis','Data integration','Demographic analysis','Python','Data visualization','Research methodology','Scientific communication'].map(s=>`<span>${s}</span>`).join('')}</div><p>On-demand road routing and exploratory resource placement extend this version. Routing uses OSRM and OpenStreetMap; resource placement compares tract-center candidates using geographic distance. Neither provides operational recommendations. This independent portfolio project is not affiliated with or endorsed by ORNL, DOE, or the source agencies.</p><a href="data/README.md" download>↓ Technical documentation</a> · <a href="data/analysis.py" download>↓ Python analysis</a>`)}
function exportData(){const isScreen=location.hash==='#screen',rows=isScreen?screenRows():data().filter(r=>location.hash!=='#explorer'||filterCounty==='all'||r.COUNTY===filterCounty+' County'),columns=['FIPS','COUNTY','LOCATION','E_TOTPOP','RPL_THEMES','EP_POV150','MP_POV150','EP_DISABL','MP_DISABL','EP_AGE65','EP_NOVEH','EP_NOINT','distance','nearest',hazard],criteria=isScreen?JSON.stringify({geography:screenGeo,county:screenCounty,minimumSVI:screenSVI,minimumDistanceKm:screenDistance,minimumHazardEAL:screenHazard}):'',exportRows=rows.map(r=>({...r,selected_score:value(r)})),csv=AtlasExports.buildAnalysisCSV(exportRows,{columns,metadata:{service,mode,indicator,weights:weights.join('|'),hazard_resolution:'county',access_method:'boundary-box center great-circle km',screen_criteria:criteria}});AtlasExports.downloadText(isScreen?`east-tennessee-threshold-screen-${screenGeo}.csv`:`east-tennessee-${geo}-${mode}.csv`,csv,'text/csv;charset=utf-8')}
function bindPage(){if($('#export'))$('#export').onclick=exportData;if($('#explorer-geo'))$('#explorer-geo').onchange=e=>{geo=e.target.value;$('#geography').value=geo;selected=null;draw();profile();render()};if($('#compare-a')){$('#compare-a').onchange=e=>{compareA=e.target.value;render()};$('#compare-b').onchange=e=>{compareB=e.target.value;render()}}if($('#explorer-county')){$('#explorer-county').onchange=e=>{filterCounty=e.target.value;render()};$('#explorer-x').onchange=e=>{explorerX=e.target.value;render()}}if($('#service-select'))$('#service-select').onchange=e=>{service=e.target.value;computeAccess();mode='accessibility';draw();profile();render()};if($('#run-scenario')){$('#scenario-county').onchange=e=>scenarioCounty=e.target.value;$('#scenario-service').onchange=e=>{service=e.target.value;computeAccess();draw();profile()};$('#detour').oninput=e=>{detour=Number(e.target.value);$('#detour-label').textContent=e.target.value+' km'};$('#run-scenario').onclick=runScenario;runScenario()}document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleShortlist(b.dataset.pin)});if($('#clear-shortlist'))$('#clear-shortlist').onclick=()=>{shortlist=[];render()};document.querySelectorAll('[data-weight]').forEach(i=>i.oninput=e=>{weights[Number(i.dataset.weight)]=Number(e.target.value);$('#weight-label-'+i.dataset.weight).textContent=e.target.value+' parts'});if($('#apply-weights'))$('#apply-weights').onclick=()=>{if(weights.every(w=>w===0)){$('#weight-note').textContent='At least one weight must be greater than zero.';return}indicator='custom';hazardView=false;document.querySelector('[name=indicator][value=custom]').checked=true;mode='vulnerability';draw();location.hash='map';render()}}
try{const loaded=await Promise.all(['svi.json','counties.geojson','tracts.json','tracts.geojson','facilities.json','hazards.json'].map(p=>fetch('data/'+p).then(r=>{if(!r.ok)throw Error(p);return r.json()})));const [svi,boundaries,tracts,tbound,fs,hz]=loaded;countyData=svi.filter(r=>EAST.includes(r.COUNTY.replace(' County','')));tractData=tracts.filter(r=>EAST.includes(r.COUNTY.replace(' County','')));shortlist=shortlist.filter(f=>[...countyData,...tractData].some(r=>r.FIPS===f));features=boundaries;tractFeatures={...tbound,features:tbound.features.filter(f=>tractData.some(r=>r.FIPS===f.properties.GEOID))};facilities=fs;const hazardLookup=Object.fromEntries(hz.features.map(f=>[f.attributes.STCOFIPS,f.attributes]));[...countyData,...tractData].forEach(r=>{r.density=Number(r.E_TOTPOP)/Number(r.AREA_SQMI);Object.assign(r,hazardLookup[r.FIPS.slice(0,5)]||{});let f=(r.FIPS.length===5?features:tractFeatures).features.find(f=>f.properties.GEOID===r.FIPS);if(f)r.center=L.geoJSON(f).getBounds().getCenter()});computeAccess();draw();metrics();profile();render();$('#geography').onchange=e=>{geo=e.target.value;selected=null;draw();profile();render()};document.querySelectorAll('[name=facilities]').forEach(i=>i.onchange=showFacilities);document.querySelector('[name=facilities][value=hospital]').checked=true;showFacilities();const hazardBox=document.createElement('div');hazardBox.innerHTML=`<div class="label">HAZARD CONTEXT · FEMA</div><label class="layer"><input type="checkbox" id="hazard-view">Show hazard loss score</label><select id="hazard-select" aria-label="Hazard context">${Object.entries(hazardNames()).map(([k,n])=>`<option value="${k}">${n[0].toUpperCase()+n.slice(1)}</option>`).join('')}</select><p class="small">County EAL percentile. Not a hazard footprint.</p>`;$('#service-layers').after(hazardBox);$('#hazard-view').onchange=e=>{hazardView=e.target.checked;draw();render()};$('#hazard-select').onchange=e=>{hazard=e.target.value;draw();render()};const researchNav=document.createElement('div');researchNav.className='subnav';researchNav.innerHTML=[['priority','Priority areas'],['profiles','Community profiles'],['shortlist','Shortlist'],['screen','Threshold screen'],['compare','County comparison'],['explorer','Data explorer'],['region','Regional overview'],['methodology','Methodology'],['sources','Data sources'],['network','Driving routes'],['placement','Resource placement'],['outage','Service outages'],['sensitivity','Model sensitivity'],['audit','Data quality'],['brief','Review brief']].map(([h,n])=>`<a href="#${h}">${n}</a>`).join('');$('main').prepend(researchNav);}catch(e){$('#profile').innerHTML='<h3>Data could not load</h3><p>Please reload to try again.</p>';console.error(e)}

if(typeof navigator!=='undefined'){try{const {initialize}=await import('./research-tools.mjs?v=20261119');extensions=await initialize({$,L,map,escapeHTML,fmt,section,countyOptions,render,hazardNames,setAnalysisContext:context=>{if(context.geo&&['county','tract'].includes(context.geo)){geo=context.geo;$('#geography').value=geo;selected=null}if(context.service&&['hospital','fire','ambulance','police','grocery','library'].includes(context.service))service=context.service;if(context.hazard&&Object.keys(hazardNames()).includes(context.hazard)){hazard=context.hazard;$('#hazard-select').value=hazard}computeAccess();draw();profile()},getState:()=>({countyData,tractData,facilities,selected,shortlist,geo,service,hazard})});render()}catch(e){console.error('Research tools unavailable',e);const n=document.createElement('p');n.className='notice';n.textContent='Additional research tools could not load. Reload to retry; the core atlas remains available.';$('#content').prepend(n)}}

